  'board_risk.acc1_content': { et: 'Juhtorganid peavad kiitma heaks küberturbe riskijuhtimise meetmed ja vastutavad isiklikult nende rakendamise eest. Juhtorganite liikmed peavad läbima küberturbe koolituse.', en: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.', fi: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.', lv: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.', lt: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.', pl: 'Management bodies must approve cybersecurity risk management measures and are personally liable for their implementation. Management body members must undergo cybersecurity training.' },
  'board_risk.acc2_title': { et: 'Trahvid ja sanktsioonid', en: 'Fines and Sanctions', fi: 'Fines and Sanctions', lv: 'Fines and Sanctions', lt: 'Fines and Sanctions', pl: 'Fines and Sanctions' },
  'board_risk.acc2_content': { et: 'Elutähtis üksus: kuni €10M või 2% käibest. Oluline üksus: kuni €7M või 1,4% käibest. Juhatuse liikme isiklik trahv kuni €500K. DORA: kuni €5M või 2% käibest.', en: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.', fi: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.', lv: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.', lt: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.', pl: 'Essential entity: up to €10M or 2% of turnover. Important entity: up to €7M or 1.4% of turnover. Board member personal fine up to €500K. DORA: up to €5M or 2% of turnover.' },
  'board_risk.acc3_title': { et: 'Millal vastutus rakendub?', en: 'When Does Liability Apply?', fi: 'When Does Liability Apply?', lv: 'When Does Liability Apply?', lt: 'When Does Liability Apply?', pl: 'When Does Liability Apply?' },
  'board_risk.acc3_content': { et: 'Kui rikkumine on tuvastatud ja juhatuse liige ei suuda tõestada mõistlike meetmete rakendamist. Vastutus võib tekkida ka hooletuse korral, kui juhatus ei ole küberturbe riske piisavalt adresseerinud.', en: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.', fi: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.', lv: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.', lt: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.', pl: 'When a violation is detected and the board member cannot prove implementation of reasonable measures. Liability may also arise from negligence if the board has not adequately addressed cybersecurity risks.' },
  'board_risk.acc4_title': { et: 'Kuidas ennast kaitsta?', en: 'How to Protect Yourself?', fi: 'How to Protect Yourself?', lv: 'How to Protect Yourself?', lt: 'How to Protect Yourself?', pl: 'How to Protect Yourself?' },
  'board_risk.acc4_content': { et: '1. Dokumenteeri kõik küberturbe otsused juhatuse protokollis. 2. Läbi küberturbe koolitus ja säilita tunnistus. 3. Kinnita riskihindamise tulemused formaalselt. 4. Taga intsidentide teavitamise protsess. 5. Kontrolli IKT-pakkujate vastavust regulaarselt.', en: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.', fi: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.', lv: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.', lt: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.', pl: '1. Document all cybersecurity decisions in board minutes. 2. Complete cybersecurity training and retain certificate. 3. Formally approve risk assessment results. 4. Ensure incident reporting process is in place. 5. Regularly verify ICT provider compliance.' },

