  'landing.review1_text': { et: 'AI lepinguaudit s\u00e4\u00e4stis meile n\u00e4dalaid konsultandi tasu. Saime kohe teada, millised klauslid puuduvad.', en: 'AI contract audit saved us weeks of consultant fees. We instantly knew which clauses were missing.', fi: 'AI contract audit saved us weeks of consultant fees. We instantly knew which clauses were missing.', lv: 'AI contract audit saved us weeks of consultant fees. We instantly knew which clauses were missing.', lt: 'AI contract audit saved us weeks of consultant fees. We instantly knew which clauses were missing.', pl: 'AI contract audit saved us weeks of consultant fees. We instantly knew which clauses were missing.' },
