  // Landing - FAQ
  'landing.faq_title': { et: 'Korduma kippuvad küsimused', en: 'Frequently Asked Questions', fi: 'Frequently Asked Questions', lv: 'Frequently Asked Questions', lt: 'Frequently Asked Questions', pl: 'Frequently Asked Questions' },
  'landing.faq1_q': { et: 'Kas DoraAudit asendab juristi?', en: 'Does DoraAudit replace a lawyer?', fi: 'Does DoraAudit replace a lawyer?', lv: 'Does DoraAudit replace a lawyer?', lt: 'Does DoraAudit replace a lawyer?', pl: 'Does DoraAudit replace a lawyer?' },
  'landing.faq1_a': { et: 'Ei. DoraAudit on eelkontrolli tööriist, mis tuvastab puudused enne kui jurist üle vaatab. Säästad juristi tunde seal, kus kõik on korras.', en: 'No. DoraAudit is a pre-check tool that identifies gaps before a lawyer reviews. You save lawyer hours where everything is already in order.', fi: 'No. DoraAudit is a pre-check tool that identifies gaps before a lawyer reviews. You save lawyer hours where everything is already in order.', lv: 'No. DoraAudit is a pre-check tool that identifies gaps before a lawyer reviews. You save lawyer hours where everything is already in order.', lt: 'No. DoraAudit is a pre-check tool that identifies gaps before a lawyer reviews. You save lawyer hours where everything is already in order.', pl: 'No. DoraAudit is a pre-check tool that identifies gaps before a lawyer reviews. You save lawyer hours where everything is already in order.' },
  'landing.faq2_q': { et: 'Kui täpne on analüüs?', en: 'How accurate is the analysis?', fi: 'How accurate is the analysis?', lv: 'How accurate is the analysis?', lt: 'How accurate is the analysis?', pl: 'How accurate is the analysis?' },
  'landing.faq2_a': { et: 'Analüüs põhineb DORA Art. 30 ametlikul tekstil ja Finantsinspektsiooni juhistel. AI-toega süsteem kontrollib 8 põhinõuet ja annab konkreetsed soovitused.', en: 'Analysis is based on official DORA Art. 30 text and Financial Supervisory Authority guidelines. AI-powered system checks 8 core requirements and provides specific recommendations.', fi: 'Analysis is based on official DORA Art. 30 text and Financial Supervisory Authority guidelines. AI-powered system checks 8 core requirements and provides specific recommendations.', lv: 'Analysis is based on official DORA Art. 30 text and Financial Supervisory Authority guidelines. AI-powered system checks 8 core requirements and provides specific recommendations.', lt: 'Analysis is based on official DORA Art. 30 text and Financial Supervisory Authority guidelines. AI-powered system checks 8 core requirements and provides specific recommendations.', pl: 'Analysis is based on official DORA Art. 30 text and Financial Supervisory Authority guidelines. AI-powered system checks 8 core requirements and provides specific recommendations.' },
  'landing.faq3_q': { et: 'Kas mu andmed on turvalised?', en: 'Is my data secure?', fi: 'Is my data secure?', lv: 'Is my data secure?', lt: 'Is my data secure?', pl: 'Is my data secure?' },
  'landing.faq3_a': { et: 'Lepingu sisu töödeldakse reaalajas ja ei salvestata serverisse. Andmed jäävad sinu brauserisse. Self-hosted variant on saadaval enterprise klientidele.', en: 'Contract content is processed in real-time and not stored on the server. Data stays in your browser. Self-hosted variant is available for enterprise clients.', fi: 'Contract content is processed in real-time and not stored on the server. Data stays in your browser. Self-hosted variant is available for enterprise clients.', lv: 'Contract content is processed in real-time and not stored on the server. Data stays in your browser. Self-hosted variant is available for enterprise clients.', lt: 'Contract content is processed in real-time and not stored on the server. Data stays in your browser. Self-hosted variant is available for enterprise clients.', pl: 'Contract content is processed in real-time and not stored on the server. Data stays in your browser. Self-hosted variant is available for enterprise clients.' },
  'landing.faq4_q': { et: 'Kes DoraAudit\'i taga on?', en: 'Who is behind DoraAudit?', fi: 'Who is behind DoraAudit?', lv: 'Who is behind DoraAudit?', lt: 'Who is behind DoraAudit?', pl: 'Who is behind DoraAudit?' },
  'landing.faq4_a': { et: 'Doraaudit, Tallinn. Meeskond kombineerib finantssektori regulatsiooni tundmist ja tarkvara arenduse kogemust.', en: 'Doraaudit, Tallinn. The team combines financial sector regulatory knowledge with software development experience.', fi: 'Doraaudit, Tallinn. The team combines financial sector regulatory knowledge with software development experience.', lv: 'Doraaudit, Tallinn. The team combines financial sector regulatory knowledge with software development experience.', lt: 'Doraaudit, Tallinn. The team combines financial sector regulatory knowledge with software development experience.', pl: 'Doraaudit, Tallinn. The team combines financial sector regulatory knowledge with software development experience.' },
  'landing.faq5_q': { et: 'Mis on Evidence Gap Analyzer?', en: 'What is the Evidence Gap Analyzer?', fi: 'What is the Evidence Gap Analyzer?', lv: 'What is the Evidence Gap Analyzer?', lt: 'What is the Evidence Gap Analyzer?', pl: 'What is the Evidence Gap Analyzer?' },
  'landing.faq5_a': { et: 'Evidence Gap Analyzer on AI-põhine tööriist, mis analüüsib teie üleslaaditud dokumente (poliitikad, protseduurid, testiaruanded) konkreetsete DORA artiklite nõuete vastu. AI hindab 45 alanõuet 10 artiklist ja annab iga nõude kohta staatuse: leitud, osaline või puudu. Tulemus sisaldab tsitaate dokumendist ja soovitusi puuduste kõrvaldamiseks. Saadaval Enterprise plaanil.', en: 'The Evidence Gap Analyzer is an AI-powered tool that analyzes your uploaded documents (policies, procedures, test reports) against specific DORA article requirements. AI evaluates 45 sub-requirements across 10 articles and provides a status for each: found, partial, or missing. Results include quotes from your document and recommendations for addressing gaps. Available on the Enterprise plan.', fi: 'The Evidence Gap Analyzer is an AI-powered tool that analyzes your uploaded documents (policies, procedures, test reports) against specific DORA article requirements. AI evaluates 45 sub-requirements across 10 articles and provides a status for each: found, partial, or missing. Results include quotes from your document and recommendations for addressing gaps. Available on the Enterprise plan.', lv: 'The Evidence Gap Analyzer is an AI-powered tool that analyzes your uploaded documents (policies, procedures, test reports) against specific DORA article requirements. AI evaluates 45 sub-requirements across 10 articles and provides a status for each: found, partial, or missing. Results include quotes from your document and recommendations for addressing gaps. Available on the Enterprise plan.', lt: 'The Evidence Gap Analyzer is an AI-powered tool that analyzes your uploaded documents (policies, procedures, test reports) against specific DORA article requirements. AI evaluates 45 sub-requirements across 10 articles and provides a status for each: found, partial, or missing. Results include quotes from your document and recommendations for addressing gaps. Available on the Enterprise plan.', pl: 'The Evidence Gap Analyzer is an AI-powered tool that analyzes your uploaded documents (policies, procedures, test reports) against specific DORA article requirements. AI evaluates 45 sub-requirements across 10 articles and provides a status for each: found, partial, or missing. Results include quotes from your document and recommendations for addressing gaps. Available on the Enterprise plan.' },

