  // About page
  'nav.about': { et: 'Meist', en: 'About', fi: 'About', lv: 'About', lt: 'About', pl: 'About' },
  'about.title': { et: 'DORA Art. 30 meeskond', en: 'DORA Art. 30 Team', fi: 'DORA Art. 30 Team', lv: 'DORA Art. 30 Team', lt: 'DORA Art. 30 Team', pl: 'DORA Art. 30 Team' },
  'about.subtitle': { et: 'Ehitame Eesti finantssektorile automatiseeritud vastavuskontrolli', en: 'Building automated compliance checking for the Estonian financial sector', fi: 'Building automated compliance checking for the Estonian financial sector', lv: 'Building automated compliance checking for the Estonian financial sector', lt: 'Building automated compliance checking for the Estonian financial sector', pl: 'Building automated compliance checking for the Estonian financial sector' },
  'about.mission_title': { et: 'Meie missioon', en: 'Our mission', fi: 'Our mission', lv: 'Our mission', lt: 'Our mission', pl: 'Our mission' },
  'about.mission_desc': { et: 'DORA regulatsioon nõuab kõigilt finantssektori ettevõtetelt, et nende IKT-lepingud vastaksid rangetele nõuetele. Me automatiseerime selle kontrolli, säästes teile aega ja raha.', en: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.', fi: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.', lv: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.', lt: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.', pl: 'DORA regulation requires all financial sector companies to have ICT contracts that meet strict requirements. We automate this check, saving you time and money.' },
  'about.why_title': { et: 'Miks me seda teeme', en: 'Why we do this', fi: 'Why we do this', lv: 'Why we do this', lt: 'Why we do this', pl: 'Why we do this' },
  'about.why_1': { et: 'DORA kohaldub alates 2025. aastast kõigile EL finantssektori ettevõtetele', en: 'DORA applies from 2025 to all EU financial sector companies', fi: 'DORA applies from 2025 to all EU financial sector companies', lv: 'DORA applies from 2025 to all EU financial sector companies', lt: 'DORA applies from 2025 to all EU financial sector companies', pl: 'DORA applies from 2025 to all EU financial sector companies' },
  'about.why_2': { et: 'Manuaalne lepingute kontroll on aeglane ja kallis (juristide tunnihind 200-400 EUR)', en: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)', fi: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)', lv: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)', lt: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)', pl: 'Manual contract review is slow and expensive (lawyer hourly rate 200-400 EUR)' },
  'about.why_3': { et: 'Trahvid mittevastavuse eest võivad ulatuda kuni 2% aastasest käibest', en: 'Fines for non-compliance can reach up to 2% of annual turnover', fi: 'Fines for non-compliance can reach up to 2% of annual turnover', lv: 'Fines for non-compliance can reach up to 2% of annual turnover', lt: 'Fines for non-compliance can reach up to 2% of annual turnover', pl: 'Fines for non-compliance can reach up to 2% of annual turnover' },
  'about.why_4': { et: 'Eestis puudus seni eestikeelne automatiseeritud lahendus', en: 'Estonia lacked an Estonian-language automated solution until now', fi: 'Estonia lacked an Estonian-language automated solution until now', lv: 'Estonia lacked an Estonian-language automated solution until now', lt: 'Estonia lacked an Estonian-language automated solution until now', pl: 'Estonia lacked an Estonian-language automated solution until now' },
  'about.founder_title': { et: 'Asutaja', en: 'Founder', fi: 'Founder', lv: 'Founder', lt: 'Founder', pl: 'Founder' },
  'about.founder_bio': { et: 'Tarkvaraarendaja ja regulatiivse tehnoloogia spetsialist 10+ aasta kogemusega. Erikompetents finantssektori compliance automatiseerimises, DORA ja NIS2 regulatsioonide rakendamises.', en: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.', fi: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.', lv: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.', lt: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.', pl: 'Software engineer and regulatory technology specialist with 10+ years of experience. Specializing in financial sector compliance automation, DORA and NIS2 regulation implementation.' },
