  'about.tech_4': { et: 'Automaatne skaleerumine', en: 'Auto-scaling infrastructure', fi: 'Auto-scaling infrastructure', lv: 'Auto-scaling infrastructure', lt: 'Auto-scaling infrastructure', pl: 'Auto-scaling infrastructure' },
  'about.methodology_title': { et: 'Metoodika', en: 'Methodology', fi: 'Methodology', lv: 'Methodology', lt: 'Methodology', pl: 'Methodology' },
  'about.methodology_desc': { et: 'DoraAudit metoodika põhineb DORA (EU) 2022/2554 ametlikul tekstil, Euroopa Pangandusjärelevalve (EBA) ja ESMA tehnilisel standarditel, Eesti Finantsinspektsiooni juhistel ning E-ITS raamistikul. Analüüsimudelid on välja töötatud koostöös finantssektori compliance spetsialistidega.', en: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.', fi: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.', lv: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.', lt: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.', pl: 'DoraAudit methodology is based on the official text of DORA (EU) 2022/2554, EBA and ESMA technical standards, Estonian Financial Supervision Authority guidelines, and the E-ITS framework. Analysis models have been developed in collaboration with financial sector compliance specialists.' },
