  'onboarding.step4_desc': { et: 'Reaalajas \u00fclevaade k\u00f5igist IKT kolmandate osapoolte s\u00f5ltuvustest. Simuleerige CTPP t\u00f5rkeid ja j\u00e4lgige riske kogu tarneahelas.', en: 'Real-time overview of all ICT third-party dependencies. Simulate CTPP failures and monitor risks across the entire supply chain.', fi: 'Real-time overview of all ICT third-party dependencies. Simulate CTPP failures and monitor risks across the entire supply chain.', lv: 'Real-time overview of all ICT third-party dependencies. Simulate CTPP failures and monitor risks across the entire supply chain.', lt: 'Real-time overview of all ICT third-party dependencies. Simulate CTPP failures and monitor risks across the entire supply chain.', pl: 'Real-time overview of all ICT third-party dependencies. Simulate CTPP failures and monitor risks across the entire supply chain.' },
