  'vendorcat.critical_explanation': { et: 'Hankija pakub teenuseid, mis toetavad kriitilisi ärifunktsioone. Teenuse katkemine avaldaks tõsist mõju klientidele, tehingutele ja regulatiivsele vastavusele. DORA nõuab kõrgendatud järelevalvet.', en: 'The vendor provides services supporting critical business functions. Service disruption would seriously impact clients, transactions, and regulatory compliance. DORA requires enhanced oversight.', fi: 'The vendor provides services supporting critical business functions. Service disruption would seriously impact clients, transactions, and regulatory compliance. DORA requires enhanced oversight.', lv: 'The vendor provides services supporting critical business functions. Service disruption would seriously impact clients, transactions, and regulatory compliance. DORA requires enhanced oversight.', lt: 'The vendor provides services supporting critical business functions. Service disruption would seriously impact clients, transactions, and regulatory compliance. DORA requires enhanced oversight.', pl: 'The vendor provides services supporting critical business functions. Service disruption would seriously impact clients, transactions, and regulatory compliance. DORA requires enhanced oversight.' },
  'vendorcat.important_explanation': { et: 'Hankija pakub olulisi teenuseid, kuid need ei ole otseselt seotud kriitiliste funktsioonidega. Teenuse katkemine oleks talutav lühiajaliselt, kuid nõuab siiski järelevalvet ja väljumisstrateegiat.', en: 'The vendor provides important services but not directly supporting critical functions. Short-term disruption would be tolerable but still requires oversight and exit strategy.', fi: 'The vendor provides important services but not directly supporting critical functions. Short-term disruption would be tolerable but still requires oversight and exit strategy.', lv: 'The vendor provides important services but not directly supporting critical functions. Short-term disruption would be tolerable but still requires oversight and exit strategy.', lt: 'The vendor provides important services but not directly supporting critical functions. Short-term disruption would be tolerable but still requires oversight and exit strategy.', pl: 'The vendor provides important services but not directly supporting critical functions. Short-term disruption would be tolerable but still requires oversight and exit strategy.' },
  'vendorcat.normal_explanation': { et: 'Hankija pakub tugiteenuseid, mille katkemine ei mõjuta otseselt äritegevust ega klientide teenindamist. Standardne haldusrežiim on piisav.', en: 'The vendor provides support services whose disruption would not directly affect business operations or client services. Standard management regime is sufficient.', fi: 'The vendor provides support services whose disruption would not directly affect business operations or client services. Standard management regime is sufficient.', lv: 'The vendor provides support services whose disruption would not directly affect business operations or client services. Standard management regime is sufficient.', lt: 'The vendor provides support services whose disruption would not directly affect business operations or client services. Standard management regime is sufficient.', pl: 'The vendor provides support services whose disruption would not directly affect business operations or client services. Standard management regime is sufficient.' },

