@Injectable({ providedIn: 'root' })
export class LangService {
  private langSignal = signal<Lang>(this.getStoredLang() || 'en');
  private geoDetectionDone = false;

  lang = this.langSignal.asReadonly();

  constructor() {
    this.updateHtmlLang(this.langSignal());
    // Default is English for European companies - no auto-detection
  }

  private getStoredLang(): Lang | null {
    if (typeof localStorage !== 'undefined') {
      // v2 key - ignores old auto-detected preferences
      const stored = localStorage.getItem('user-lang-choice') as Lang;
      if (['et', 'en', 'fi', 'lv', 'lt', 'pl'].includes(stored)) {
        return stored;
      }
    }
    return null;
  }

  private async detectByGeolocation(): Promise<void> {
    if (this.geoDetectionDone || typeof fetch === 'undefined') return;
    this.geoDetectionDone = true;

    try {
      const response = await fetch(GEOLOCATION_API, {
        signal: AbortSignal.timeout(3000) // 3 second timeout
      });
      if (!response.ok) return;

      const data = await response.json();
      // If user is in Baltic states, switch to local language
      if (!this.getStoredLang()) {
        const countryLangMap: Record<string, Lang> = { 'EE': 'et', 'FI': 'fi', 'LV': 'lv', 'LT': 'lt', 'PL': 'pl' };
        const detectedLang = countryLangMap[data.country_code];
        if (detectedLang) {
          this.langSignal.set(detectedLang);
          this.updateHtmlLang(detectedLang);
        }
      }
    } catch {
      // Silently fail - keep default English
    }
  }

  get currentLang(): Lang {
    return this.langSignal();
  }

  private static readonly LANG_CYCLE: Lang[] = ['en', 'et', 'fi', 'lv', 'lt', 'pl'];

  toggle() {
    const current = this.langSignal();
    const idx = LangService.LANG_CYCLE.indexOf(current);
    const next = LangService.LANG_CYCLE[(idx + 1) % LangService.LANG_CYCLE.length];
    this.setLang(next);
  }

  setLang(lang: Lang) {
    this.langSignal.set(lang);
    if (typeof localStorage !== 'undefined') localStorage.setItem('user-lang-choice', lang);
    this.updateHtmlLang(lang);
  }

  get availableLanguages(): { code: Lang; label: string }[] {
    return [
      { code: 'en', label: 'English' },
      { code: 'et', label: 'Eesti' },
      { code: 'fi', label: 'Suomi' },
      { code: 'lv', label: 'Latviešu' },
      { code: 'lt', label: 'Lietuvių' },
      { code: 'pl', label: 'Polski' }
    ];
  }

  private updateHtmlLang(lang: Lang) {
    if (typeof document !== 'undefined') {
      document.documentElement.lang = lang;
    }
  }

  t(key: string): string {
    const entry = TRANSLATIONS[key];
    if (!entry) return key;
    const lang = this.langSignal();
    return (entry as any)[lang] || entry['en'] || entry['et'] || key;
  }

  pick(obj: { et: string; en: string; [key: string]: string }): string {
    return obj[this.currentLang] ?? obj['en'] ?? '';
  }

  /** Shorthand for inline bilingual values: lang.l(obj.nameEt, obj.nameEn) */
  l(et: string, en: string): string {
    return this.langSignal() === 'et' ? et : en;
  }
}
